use std::fmt;
use std::path::Path;
use std::process::{Command, ExitCode};

const TYPES: &[&str] = &[
    "feat", "fix", "perf", "test", "chore", "docs", "ci", "refactor", "build", "style", "revert",
];
const ATTRIBUTION_MARKERS: &[&str] = &[
    "co-authored-by:",
    "generated with",
    "generated by",
    "🤖",
    "anthropic.com",
    "openai.com",
    "cursor.com",
    "cursoragent",
    "copilot",
];
const TEST_MARKER: &str = "#[test]";

#[derive(Debug, PartialEq, Eq)]
pub enum Problem {
    Attribution(String),
    Title,
    UntestedChange,
}

impl fmt::Display for Problem {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Problem::Attribution(marker) => write!(
                f,
                "remove the attribution (`{marker}`); the human owner is the only author"
            ),
            Problem::Title => write!(
                f,
                "start the title with `(type): ` where type is one of {}",
                TYPES.join(", ")
            ),
            Problem::UntestedChange => f.write_str(
                "add a (test) commit before this one that fails without it, or change a test in the same commit",
            ),
        }
    }
}

pub struct Commit {
    pub subject: String,
    pub message: String,
    pub merge: bool,
    pub touches_src: bool,
    pub changes_tests: bool,
}

impl Commit {
    fn kind(&self) -> Option<&str> {
        commit_type(&self.subject)
    }
}

fn commit_type(title: &str) -> Option<&str> {
    let rest = title.strip_prefix('(')?;
    let (kind, description) = rest.split_once("): ")?;
    (TYPES.contains(&kind) && !description.trim().is_empty()).then_some(kind)
}

fn attribution(message: &str) -> Option<String> {
    let lower = message.to_lowercase();
    ATTRIBUTION_MARKERS
        .iter()
        .find(|marker| lower.contains(*marker))
        .map(|marker| (*marker).to_owned())
}

pub fn check(commits: &[Commit], title: Option<&str>) -> Vec<(String, Problem)> {
    let mut problems = Vec::new();
    if let Some(title) = title {
        if commit_type(title).is_none() {
            problems.push((title.to_owned(), Problem::Title));
        }
        if let Some(marker) = attribution(title) {
            problems.push((title.to_owned(), Problem::Attribution(marker)));
        }
    }
    let mut tested = false;
    for commit in commits.iter().filter(|commit| !commit.merge) {
        if let Some(marker) = attribution(&commit.message) {
            problems.push((commit.subject.clone(), Problem::Attribution(marker)));
        }
        match commit.kind() {
            None => problems.push((commit.subject.clone(), Problem::Title)),
            Some("test") => tested = true,
            Some("fix" | "perf") if commit.touches_src && !tested && !commit.changes_tests => {
                problems.push((commit.subject.clone(), Problem::UntestedChange));
            }
            Some(_) => {}
        }
    }
    problems
}

fn git(root: &Path, args: &[&str]) -> Option<String> {
    let output = Command::new("git")
        .args(args)
        .current_dir(root)
        .output()
        .ok()
        .filter(|output| output.status.success())?;
    String::from_utf8(output.stdout).ok()
}

fn load(root: &Path, sha: &str) -> Option<Commit> {
    let header = git(root, &["show", "-s", "--format=%P%x00%s%x00%B", sha])?;
    let mut fields = header.splitn(3, '\0');
    let parents = fields.next()?;
    let subject = fields.next()?.to_owned();
    let message = fields.next()?.to_owned();
    let patch = git(root, &["show", "--format=", "-U0", sha])?;
    let files: Vec<&str> = patch
        .lines()
        .filter_map(|line| line.strip_prefix("+++ b/"))
        .collect();
    Some(Commit {
        subject,
        message,
        merge: parents.split_whitespace().count() > 1,
        touches_src: files.iter().any(|file| file.starts_with("src/")),
        changes_tests: files.iter().any(|file| file.starts_with("tests/"))
            || patch
                .lines()
                .any(|line| line.starts_with('+') && line.contains(TEST_MARKER)),
    })
}

pub fn run(root: &Path, range: Option<&str>, title: Option<&str>) -> ExitCode {
    let Some(range) = range else {
        eprintln!("usage: cargo xtask commits <base>..<head> [pr title]");
        return ExitCode::FAILURE;
    };
    let Some(list) = git(root, &["rev-list", "--reverse", range]) else {
        eprintln!("could not list the commits in {range}");
        return ExitCode::FAILURE;
    };
    let mut commits = Vec::new();
    for sha in list.lines() {
        let Some(commit) = load(root, sha) else {
            eprintln!("could not read commit {sha}");
            return ExitCode::FAILURE;
        };
        commits.push(commit);
    }
    let problems = check(&commits, title.filter(|title| !title.is_empty()));
    for (subject, problem) in &problems {
        eprintln!("{subject}: {problem}");
    }
    if problems.is_empty() {
        println!("{} commit(s) in {range} pass", commits.len());
        ExitCode::SUCCESS
    } else {
        eprintln!("{} commit message problem(s)", problems.len());
        ExitCode::FAILURE
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn commit(subject: &str, touches_src: bool, changes_tests: bool) -> Commit {
        Commit {
            subject: subject.to_owned(),
            message: format!("{subject}\n"),
            merge: false,
            touches_src,
            changes_tests,
        }
    }

    #[test]
    fn flags_attribution_titles_and_untested_fixes() {
        let mut attributed = commit("(feat): add search", true, false);
        attributed
            .message
            .push_str("\nCo-authored-by: Claude <noreply@anthropic.com>\n");
        let mut merge = commit("Merge branch 'master'", false, false);
        merge.merge = true;
        let commits = [
            attributed,
            commit("perf: faster", false, false),
            commit("(fix): untested", true, false),
            commit("(fix): ci only", false, false),
            commit("(fix): with its own test", true, true),
            merge,
            commit("(test): fails first", false, true),
            commit("(perf): tested", true, false),
        ];
        let problems: Vec<Problem> = check(&commits, Some("Add search"))
            .into_iter()
            .map(|(_, problem)| problem)
            .collect();
        assert_eq!(
            problems,
            [
                Problem::Title,
                Problem::Attribution("co-authored-by:".to_owned()),
                Problem::Title,
                Problem::UntestedChange,
            ]
        );
    }
}
